## 3.3 Top 10 States, reference year 2025-26


::: {.cell}

```{.r .cell-code}
top10 <- ref[rank <= 10]
top10[, tip := sprintf("%s<br>%.1f LMT (%.1f%% of crop total)", State, Total, share)]
top10[, id := paste(Crop, State)]

p3 <- ggplot(top10, aes(x = reorder(State, Total), y = Total, fill = Crop)) +
  geom_col_interactive(aes(tooltip = tip, data_id = id), width = 0.7) +
  geom_text(aes(label = sprintf("%.0f", Total)), hjust = -0.2, size = 3) +
  coord_flip() +
  facet_wrap(~Crop, scales = "free") +
  scale_fill_manual(values = crop_cols, guide = "none") +
  scale_y_continuous(expand = expansion(mult = c(0, 0.15))) +
  labs(
    title = "Top ten states by volume",
    subtitle = "Procurement is led by a small group of states, 2025-26, lakh metric tonnes (LMT)",
    caption = "Source: DFPD Central Food Grains Procurement Portal. Shares are of each crop's national total in the same year."
  ) +
  econ_theme +
  theme(
    panel.grid.major.x = element_line(colour = "#A9BFCB", linewidth = 0.4),
    panel.grid.major.y = element_blank()
  )

girafe(ggobj = p3, width_svg = 9, height_svg = 5.5)
```

