## 3.4 Concentration Over Time


::: {.cell}

```{.r .cell-code}
hhi_t[, tip := sprintf("%s (%s)<br>HHI: %.0f<br>States reporting: %d", Crop, MarketingYear, HHI, states)]
hhi_t[, id := paste(Crop, MarketingYear)]

p4 <- ggplot(hhi_t, aes(x = start_year, y = HHI, colour = Crop, group = Crop)) +
  geom_hline(yintercept = 1500, linetype = "dashed", colour = "grey40", linewidth = 0.4) +
  geom_line(linewidth = 0.9) +
  geom_point_interactive(aes(tooltip = tip, data_id = id), size = 2) +
  geom_text(data = hhi_t[, .SD[.N], by = Crop], aes(label = round(HHI, 0)),
    hjust = -0.35, size = 3.2, show.legend = FALSE) +
  scale_colour_manual(values = crop_cols) +
  scale_x_continuous(breaks = seq(2002, 2026, by = 4), expand = expansion(mult = c(0.02, 0.08))) +
  labs(
    title = "Herfindahl-Hirschman Index by year",
    subtitle = "Paddy procurement has spread across more states; wheat stays concentrated. 
    Dashed line = 1,500 (unconcentrated threshold). Labels show the latest year",
    caption = "Source: DFPD Central Food Grains Procurement Portal. Higher values mean procurement is dominated by fewer states."
  ) +
  econ_theme

girafe(ggobj = p4, width_svg = 9, height_svg = 4.8)
```

