## 3.5 Paddy Procurement by Channel


::: {.cell}

```{.r .cell-code}
chan_long[, tip := sprintf("%s<br>%s: %.1f LMT<br>State agency share: %.1f%%",
  MarketingYear, ifelse(Agency == "FCI", "FCI", "State agency"), qty, sa_share)]
chan_long[, id := paste(MarketingYear, Agency)]

p5 <- ggplot(chan_long, aes(x = start_year, y = qty, fill = Agency)) +
  geom_col_interactive(aes(tooltip = tip, data_id = id), width = 0.8) +
  geom_text(data = chan, inherit.aes = FALSE,
    aes(x = start_year, y = FCI + StateAgency, label = sprintf("%.0f%%", sa_share)),
    vjust = -0.4, size = 2.8) +
  scale_fill_manual(values = c(FCI = "#006BA2", StateAgency = "#E3120B"),
    labels = c(FCI = "FCI", StateAgency = "State agency")) +
  scale_x_continuous(breaks = seq(2008, 2022, by = 2)) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.1))) +
  labs(
    title = "Paddy Procurement",
    subtitle = "State agencies now handle almost all Paddy procurement
    Unit in lakh metric tonnes (LMT). Labels show the state-agency share",
    caption = "Source: DFPD Central Food Grains Procurement Portal. The split is available up to 2021-22."
  ) +
  econ_theme

girafe(ggobj = p5, width_svg = 9, height_svg = 4.8)
```

