```{.r .cell-code}
area_paddy <- state_ts[Crop == "Paddy"]

p7a <- ggplot(area_paddy, aes(x = start_year, y = Total, fill = series)) +
  geom_area_interactive(aes(tooltip = series, data_id = series),
    colour = "white", linewidth = 0.2, alpha = 0.9) +
  scale_x_continuous(breaks = seq(2008, 2026, by = 2), expand = expansion(mult = c(0.01, 0.01))) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.05))) +
  labs(
    title = "Paddy Procurement: State Composition of the National Total",
    subtitle = "Stacked area, lakh metric tonnes (LMT). Top edge equals National Paddy Procurement",
    caption = "Source: DFPD Central Food Grains Procurement Portal. Provisional 2026-27 data excluded."
  ) +
  econ_theme +
  theme(legend.position = "right", legend.justification = "top")

girafe(ggobj = p7a, width_svg = 9, height_svg = 5)
```

